# =============================================================================
#  Adaptive Rejection Sampling (ARS)
#
#  Implementation of the tangent-based adaptive rejection sampler of
#    Gilks, W. R. & Wild, P. (1992). Adaptive rejection sampling for Gibbs
#    sampling. Journal of the Royal Statistical Society, Series C, 41(2), 337-348.
#
#  Usage:
#    source("ars.R")
#    x <- ars(dnorm, 1000)                          # standard normal
#    x <- ars(dnorm, 1000, mean = 5, sd = 2)        # extra args passed to f
#    x <- ars(dexp, 1000, lower = 0, rate = 3)      # bounded domain
#    x <- ars(function(z) exp(-z^2 / 2), 1000)      # unnormalized density
#    test()                                         # run the formal test suite
#
#  Design: purely functional. Every discrete task of the algorithm is a small
#  function (snake_case); the upper/lower hulls are stored in a single list
#  object of class "ars_hull" which is created by build_hull() and replaced
#  (never mutated in place) by update_hull(). Errors are signalled as
#  classed conditions ("ars_input_error", "ars_concavity_error",
#  "ars_sampling_error", all inheriting from "ars_error") so callers and the
#  test-suite can distinguish invalid input from non-log-concavity.
#
#  Notation follows the paper:
#    h(x)  = log f(x)                    (log of the unnormalized density)
#    h'(x) = derivative of h             (user supplied or numerical)
#    T_k   = {x_1 < ... < x_k}           (abscissae)
#    z_j   = intersection of tangents at x_j and x_{j+1}
#    u_k   = piecewise-linear upper hull (tangents)
#    l_k   = piecewise-linear lower hull (chords / squeeze function)
#    s_k   = exp(u_k) / integral(exp(u_k))  (envelope density)
# =============================================================================


# -----------------------------------------------------------------------------
#  Conditions (error signalling)
# -----------------------------------------------------------------------------

#' Signal a classed ARS error.
#' @param type   condition sub-class, e.g. "ars_input_error"
#' @param ...    pieces of the message (pasted together)
ars_error <- function(type, ...) {
  cond <- structure(
    class = c(type, "ars_error", "error", "condition"),
    list(message = paste0(...), call = NULL)
  )
  stop(cond)
}

input_error     <- function(...) ars_error("ars_input_error", ...)
concavity_error <- function(...) ars_error("ars_concavity_error", ...)
sampling_error  <- function(...) ars_error("ars_sampling_error", ...)

#' Compact number formatting for messages.
fmt_num <- function(x) paste(format(signif(x, 6)), collapse = ", ")


# -----------------------------------------------------------------------------
#  Input validation
# -----------------------------------------------------------------------------

#' Check that `x` is a single non-missing number.
is_scalar_number <- function(x) {
  is.numeric(x) && length(x) == 1L && !is.na(x)
}

#' Resolve the sampling domain from `lower`/`upper` or `domain = c(lo, hi)`.
#' @return list(lower, upper)
resolve_domain <- function(lower, upper, domain = NULL) {
  if (!is.null(domain)) {
    if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain)) {
      input_error("'domain' must be a numeric vector c(lower, upper) without NAs.")
    }
    lower <- domain[1L]
    upper <- domain[2L]
  }
  if (!is_scalar_number(lower)) input_error("'lower' must be a single non-missing number (may be -Inf).")
  if (!is_scalar_number(upper)) input_error("'upper' must be a single non-missing number (may be Inf).")
  if (!(lower < upper)) {
    input_error("invalid domain: 'lower' (", fmt_num(lower), ") must be strictly less than 'upper' (",
                fmt_num(upper), ").")
  }
  list(lower = as.numeric(lower), upper = as.numeric(upper))
}

#' Validate all user-facing arguments of ars(). Signals an "ars_input_error"
#' on the first problem found; returns TRUE invisibly otherwise.
validate_inputs <- function(f, n, lower, upper, x_init, h_prime, log_density,
                            max_points, tol) {
  if (!is.function(f)) {
    input_error("'f' must be a function that returns (possibly unnormalized) density values.")
  }
  if (!is.numeric(n) || length(n) != 1L || is.na(n)) {
    input_error("'n' (number of samples) must be a single number.")
  }
  if (!is.finite(n) || n <= 0) {
    input_error("'n' (number of samples) must be a positive, finite integer; got ", fmt_num(n), ".")
  }
  if (abs(n - round(n)) > 1e-8) {
    input_error("'n' (number of samples) must be a whole number; got ", fmt_num(n), ".")
  }
  if (n > .Machine$integer.max) input_error("'n' is too large.")

  if (!is.null(x_init)) {
    if (!is.numeric(x_init) || anyNA(x_init) || any(!is.finite(x_init))) {
      input_error("'x_init' must be a numeric vector of finite values.")
    }
    if (length(x_init) < 2L) {
      input_error("'x_init' must contain at least 2 starting abscissae.")
    }
    if (anyDuplicated(x_init)) input_error("'x_init' must not contain duplicated values.")
    if (any(x_init <= lower | x_init >= upper)) {
      input_error("all 'x_init' values must lie strictly inside the domain (",
                  fmt_num(lower), ", ", fmt_num(upper), ").")
    }
  }
  if (!is.null(h_prime) && !is.function(h_prime)) {
    input_error("'h_prime' must be NULL or a function returning the derivative of log f.")
  }
  if (!is.logical(log_density) || length(log_density) != 1L || is.na(log_density)) {
    input_error("'log_density' must be TRUE or FALSE.")
  }
  if (!is_scalar_number(max_points) || !is.finite(max_points) || max_points < 3 ||
      abs(max_points - round(max_points)) > 1e-8) {
    input_error("'max_points' must be a whole number >= 3.")
  }
  if (!is_scalar_number(tol) || !is.finite(tol) || tol <= 0) {
    input_error("'tol' must be a single positive number.")
  }
  invisible(TRUE)
}


# -----------------------------------------------------------------------------
#  Log density and its derivative
# -----------------------------------------------------------------------------

#' Build h(x) = log f(x) from the user's (vectorized) density.
#'
#' The returned closure checks that f is vectorized and returns valid values.
#' @param f           density function, called as f(x, ...)
#' @param log_density TRUE if f already returns log-density values
#' @param args        list of extra arguments for f
#' @return function(x) returning log-density values (may be -Inf where f = 0)
make_log_density <- function(f, log_density = FALSE, args = list()) {
  force(f); force(log_density); force(args)
  function(x) {
    if (length(x) == 0L) return(numeric(0))
    val <- tryCatch(
      do.call(f, c(list(x), args)),
      error = function(e) input_error("evaluating 'f' failed: ", conditionMessage(e))
    )
    if (!is.numeric(val) || length(val) != length(x)) {
      input_error("'f' must be vectorized: it returned ", length(val), " value(s) for ",
                  length(x), " input(s).")
    }
    if (anyNA(val)) {
      input_error("'f' returned NA/NaN at x = ", fmt_num(x[is.na(val)][1L]), ".")
    }
    val <- as.numeric(val)
    if (log_density) {
      if (any(val == Inf)) input_error("log density is +Inf at x = ", fmt_num(x[val == Inf][1L]), ".")
      return(val)
    }
    if (any(val < 0)) {
      input_error("'f' returned a negative density value at x = ", fmt_num(x[val < 0][1L]), ".")
    }
    if (any(val == Inf)) input_error("density is infinite at x = ", fmt_num(x[val == Inf][1L]), ".")
    log(val)
  }
}

#' Numerical derivative of h, vectorized.
#'
#' Uses a central difference where possible and second-order one-sided
#' differences near the domain boundary or where h is -Inf on one side.
#' @param h     log-density function
#' @param x     points at which to differentiate
#' @param lower,upper domain bounds
#' @param hx    h(x) (optional, avoids re-evaluation)
numeric_derivative <- function(h, x, lower = -Inf, upper = Inf, hx = h(x)) {
  n <- length(x)
  if (n == 0L) return(numeric(0))
  eps <- 1e-5 * pmax(1, abs(x))
  d <- rep(NA_real_, n)

  central <- (x - eps > lower) & (x + eps < upper)
  if (any(central)) {
    xc <- x[central]; ec <- eps[central]
    d[central] <- (h(xc + ec) - h(xc - ec)) / (2 * ec)
  }
  fwd <- !is.finite(d) & (x + 2 * eps < upper)
  if (any(fwd)) {
    xf <- x[fwd]; ef <- eps[fwd]
    d[fwd] <- (-3 * hx[fwd] + 4 * h(xf + ef) - h(xf + 2 * ef)) / (2 * ef)
  }
  bwd <- !is.finite(d) & (x - 2 * eps > lower)
  if (any(bwd)) {
    xb <- x[bwd]; eb <- eps[bwd]
    d[bwd] <- (3 * hx[bwd] - 4 * h(xb - eb) + h(xb - 2 * eb)) / (2 * eb)
  }
  if (any(!is.finite(d))) {
    input_error("could not differentiate log f numerically at x = ", fmt_num(x[!is.finite(d)][1L]),
                " (density is zero or non-smooth arbitrarily close to this point).")
  }
  d
}

#' Build h'(x): either the user-supplied derivative or a numerical one.
#' @return function(x, hx) returning h'(x)
make_log_density_deriv <- function(h, h_prime = NULL, lower = -Inf, upper = Inf, args = list()) {
  force(h); force(h_prime); force(lower); force(upper); force(args)
  if (is.null(h_prime)) {
    return(function(x, hx = h(x)) numeric_derivative(h, x, lower, upper, hx))
  }
  function(x, hx = NULL) {
    if (length(x) == 0L) return(numeric(0))
    val <- tryCatch(
      do.call(h_prime, c(list(x), args)),
      error = function(e) input_error("evaluating 'h_prime' failed: ", conditionMessage(e))
    )
    if (!is.numeric(val) || length(val) != length(x)) {
      input_error("'h_prime' must be vectorized and return one value per input.")
    }
    if (any(!is.finite(val))) {
      input_error("'h_prime' returned a non-finite value at x = ", fmt_num(x[!is.finite(val)][1L]), ".")
    }
    as.numeric(val)
  }
}


# -----------------------------------------------------------------------------
#  Initialisation of the abscissae
# -----------------------------------------------------------------------------

#' Find one point inside the domain where h is finite.
find_start_point <- function(h, lower, upper) {
  offsets <- c(1, as.vector(rbind(2^(1:40), 2^-(1:40))))
  cand <- if (is.finite(lower) && is.finite(upper)) {
    lower + (upper - lower) * c(0.5, (1:199) / 200)
  } else if (is.finite(lower)) {
    lower + offsets
  } else if (is.finite(upper)) {
    upper - offsets
  } else {
    c(0, as.vector(rbind(offsets, -offsets)))
  }
  hc <- h(cand)
  ok <- which(is.finite(hc))
  if (length(ok) == 0L) {
    input_error("could not find any point in the domain where the density is positive; ",
                "check 'f' and the domain or supply 'x_init'.")
  }
  cand[ok[1L]]
}

#' Walk from x0 in direction `dir` (+1 / -1) until the slope of h has the sign
#' required for a bounded envelope (h' < 0 to the right, h' > 0 to the left).
#' The step doubles after a successful move and shrinks if h becomes -Inf.
search_direction <- function(h, hp, x0, dir, max_steps = 100L) {
  x <- x0
  step <- 1
  for (i in seq_len(max_steps)) {
    if (dir * hp(x) < 0) return(x)
    cand <- x + dir * step
    if (is.finite(h(cand))) {
      x <- cand
      step <- 2 * step
    } else {
      step <- step / 4
    }
  }
  input_error("could not find a starting point with ", if (dir > 0) "negative" else "positive",
              " log-density slope towards ", if (dir > 0) "+Inf" else "-Inf",
              ". The density may not be integrable/log-concave on this domain, its support may ",
              "be smaller than the domain (set 'lower'/'upper'), or its scale is extreme ",
              "(supply 'x_init').")
}

#' Choose initial abscissae T_k automatically (Gilks & Wild section 2.2.1):
#' if the domain is unbounded on the left, the leftmost point must have
#' h' > 0; if unbounded on the right, the rightmost must have h' < 0.
#' @return sorted numeric vector of at least 2 points
find_init_points <- function(h, hp, lower, upper) {
  if (is.finite(lower) && is.finite(upper)) {
    grid <- lower + (upper - lower) * (1:199) / 200
    idx <- which(is.finite(h(grid)))
    if (length(idx) < 2L) {
      input_error("the density is positive at fewer than 2 grid points of the domain; supply 'x_init'.")
    }
    pick <- unique(round(c(0.2, 0.5, 0.8) * (length(idx) - 1)) + 1)
    return(grid[idx[pick]])
  }
  x0 <- find_start_point(h, lower, upper)
  pts <- x0
  if (lower == -Inf) pts <- c(pts, search_direction(h, hp, x0, dir = -1))
  if (upper == Inf)  pts <- c(pts, search_direction(h, hp, x0, dir = +1))
  pts <- sort(unique(pts))
  if (length(pts) < 2L) {
    bound <- if (is.finite(lower)) lower else upper
    extra <- (x0 + bound) / 2
    if (!is.finite(h(extra))) extra <- if (is.finite(lower)) x0 + 1 else x0 - 1
    pts <- sort(c(pts, extra))
  }
  pts
}


# -----------------------------------------------------------------------------
#  Log-concavity checks
# -----------------------------------------------------------------------------

#' Check that sorted abscissae with values hx and slopes hpx are consistent
#' with a concave h: h'(x_j) >= (h(x_{j+1}) - h(x_j)) / (x_{j+1} - x_j) >= h'(x_{j+1}).
#' Small numerical slack (relative tolerance `tol`) is allowed.
#' Signals "ars_concavity_error" on violation.
check_log_concavity <- function(x, hx, hpx, tol = 1e-6) {
  k <- length(x)
  if (k < 2L) return(invisible(TRUE))
  dx <- diff(x)
  secant <- diff(hx) / dx
  hp1 <- hpx[-k]; hp2 <- hpx[-1L]
  hmax <- pmax(abs(hx[-k]), abs(hx[-1L]))
  slack <- tol * (1 + pmax(abs(hp1), abs(hp2))) + 1e-10 * (1 + hmax) + 1e-12 * (1 + hmax) / dx
  bad <- (hp2 - hp1 > slack) | (secant - hp1 > slack) | (hp2 - secant > slack)
  if (any(bad)) {
    j <- which(bad)[1L]
    concavity_error(
      "the density is not log-concave: between x = ", fmt_num(x[j]), " and x = ", fmt_num(x[j + 1L]),
      " the log-density slopes are h' = ", fmt_num(hp1[j]), " and ", fmt_num(hp2[j]),
      " with chord slope ", fmt_num(secant[j]),
      " (log-concavity requires h'(left) >= chord slope >= h'(right))."
    )
  }
  invisible(TRUE)
}

#' Check newly evaluated points against the hulls: for a log-concave density
#' l_k(x) <= h(x) <= u_k(x) must hold everywhere.
#' Signals "ars_concavity_error" on violation.
check_points_against_hulls <- function(x, hx, u, l, tol = 1e-6) {
  slack <- tol * (1 + abs(u))
  above <- is.finite(hx) & (hx > u + slack)
  if (any(above)) {
    j <- which(above)[1L]
    concavity_error("the density is not log-concave: log f(", fmt_num(x[j]), ") = ", fmt_num(hx[j]),
                    " lies above the tangent upper hull (", fmt_num(u[j]), ").")
  }
  below <- is.finite(l) & (hx < l - slack)
  if (any(below)) {
    j <- which(below)[1L]
    concavity_error("the density is not log-concave: log f(", fmt_num(x[j]), ") = ", fmt_num(hx[j]),
                    " lies below the chord lower hull (", fmt_num(l[j]), ").")
  }
  invisible(TRUE)
}


# -----------------------------------------------------------------------------
#  Hull construction
# -----------------------------------------------------------------------------

#' Intersections z_j of the tangents at x_j and x_{j+1} (equation (1) of the
#' paper), written in a numerically stable form. When the tangents are
#' (numerically) parallel the midpoint is used. Results are clamped to
#' [x_j, x_{j+1}].
compute_intersections <- function(x, hx, hpx) {
  k <- length(x)
  if (k < 2L) return(numeric(0))
  x1 <- x[-k]; x2 <- x[-1L]
  h1 <- hx[-k]; h2 <- hx[-1L]
  d1 <- hpx[-k]; d2 <- hpx[-1L]
  den <- d1 - d2
  z <- x1 + (h2 - h1 - (x2 - x1) * d2) / den
  flat <- !is.finite(z) | abs(den) <= 1e-12 * (1 + abs(d1) + abs(d2))
  z[flat] <- (x1[flat] + x2[flat]) / 2
  pmin(pmax(z, x1), x2)
}

#' Log of integral of exp(h_j + b_j (t - x_j)) over [zl_j, zr_j], vectorized
#' and stable for infinite limits and slopes of any sign.
segment_log_mass <- function(x, hx, hpx, zl, zr) {
  b <- hpx
  out <- numeric(length(b))
  pos <- b > 0; neg <- b < 0; zero <- b == 0
  w <- zr - zl
  out[pos]  <- hx[pos] + b[pos] * (zr[pos] - x[pos]) + log(-expm1(-b[pos] * w[pos])) - log(b[pos])
  out[neg]  <- hx[neg] + b[neg] * (zl[neg] - x[neg]) + log(-expm1(b[neg] * w[neg])) - log(-b[neg])
  out[zero] <- hx[zero] + log(w[zero])
  out[w <= 0] <- -Inf
  out
}

#' Construct the hull object from abscissae, h values and h' values.
#'
#' @return list of class "ars_hull" with elements
#'   x, h, hp     sorted abscissae, log-density, slopes
#'   z            breakpoints c(lower, z_1, ..., z_{k-1}, upper)
#'   log_mass     log integral of exp(u_k) over each segment [z_j, z_{j+1}]
#'   lower, upper domain
build_hull <- function(x, hx, hpx, lower, upper, tol = 1e-6) {
  o <- order(x)
  x <- x[o]; hx <- hx[o]; hpx <- hpx[o]
  if (any(!is.finite(hx))) {
    input_error("the density must be positive at all abscissae; f is zero at x = ",
                fmt_num(x[!is.finite(hx)][1L]), ".")
  }
  check_log_concavity(x, hx, hpx, tol)
  k <- length(x)
  if (lower == -Inf && hpx[1L] <= 0) {
    input_error("with lower = -Inf the leftmost abscissa must have a positive log-density slope ",
                "(h'(", fmt_num(x[1L]), ") = ", fmt_num(hpx[1L]), "); choose 'x_init' to the left of the mode.")
  }
  if (upper == Inf && hpx[k] >= 0) {
    input_error("with upper = Inf the rightmost abscissa must have a negative log-density slope ",
                "(h'(", fmt_num(x[k]), ") = ", fmt_num(hpx[k]), "); choose 'x_init' to the right of the mode.")
  }
  z <- c(lower, compute_intersections(x, hx, hpx), upper)
  log_mass <- segment_log_mass(x, hx, hpx, z[-(k + 1L)], z[-1L])
  if (!any(is.finite(log_mass)) || any(log_mass == Inf) || anyNA(log_mass)) {
    sampling_error("the upper hull has zero, infinite or undefined mass; the density may be improper.")
  }
  structure(list(x = x, h = hx, hp = hpx, z = z, log_mass = log_mass,
                 lower = lower, upper = upper),
            class = "ars_hull")
}

#' Add new abscissae to a hull (rejection-step update) and rebuild it.
#' Exact or near duplicates of existing abscissae are ignored.
update_hull <- function(hull, new_x, new_h, new_hp, tol = 1e-6) {
  if (length(new_x) == 0L) return(hull)
  x <- c(hull$x, new_x); hx <- c(hull$h, new_h); hpx <- c(hull$hp, new_hp)
  o <- order(x)
  x <- x[o]; hx <- hx[o]; hpx <- hpx[o]
  keep <- c(TRUE, diff(x) > 1e-10 * pmax(1, abs(x[-1L])))
  build_hull(x[keep], hx[keep], hpx[keep], hull$lower, hull$upper, tol)
}

#' Total log mass of the envelope exp(u_k).
hull_log_total_mass <- function(hull) {
  m <- max(hull$log_mass)
  m + log(sum(exp(hull$log_mass - m)))
}


# -----------------------------------------------------------------------------
#  Hull evaluation and envelope sampling
# -----------------------------------------------------------------------------

#' Evaluate the upper hull u_k(x) (piecewise tangents).
eval_upper_hull <- function(x, hull) {
  j <- findInterval(x, hull$z, rightmost.closed = TRUE, all.inside = TRUE)
  hull$h[j] + (x - hull$x[j]) * hull$hp[j]
}

#' Evaluate the lower hull l_k(x) (chords between abscissae; -Inf outside
#' [x_1, x_k]).
eval_lower_hull <- function(x, hull) {
  k <- length(hull$x)
  out <- rep(-Inf, length(x))
  if (k < 2L) return(out)
  j <- findInterval(x, hull$x, rightmost.closed = TRUE)
  inside <- j >= 1L & j <= k - 1L & x <= hull$x[k]
  if (any(inside)) {
    ji <- j[inside]; xi <- x[inside]
    x1 <- hull$x[ji]; x2 <- hull$x[ji + 1L]
    out[inside] <- ((x2 - xi) * hull$h[ji] + (xi - x1) * hull$h[ji + 1L]) / (x2 - x1)
  }
  out
}

#' Draw m independent samples from the envelope density s_k(x) by choosing a
#' segment with probability proportional to its mass and inverting the
#' (truncated exponential) CDF within that segment.
sample_envelope <- function(m, hull) {
  p <- exp(hull$log_mass - max(hull$log_mass))
  j <- sample.int(length(p), m, replace = TRUE, prob = p)
  b <- hull$hp[j]
  zl <- hull$z[j]; zr <- hull$z[j + 1L]
  u <- runif(m)
  x <- numeric(m)
  pos <- b > 0; neg <- b < 0; zero <- b == 0
  x[pos]  <- zr[pos] + log(u[pos] + (1 - u[pos]) * exp(-b[pos] * (zr[pos] - zl[pos]))) / b[pos]
  x[neg]  <- zl[neg] + log1p(u[neg] * expm1(b[neg] * (zr[neg] - zl[neg]))) / b[neg]
  x[zero] <- zl[zero] + u[zero] * (zr[zero] - zl[zero])
  pmin(pmax(x, zl), zr)
}


# -----------------------------------------------------------------------------
#  One sampling round: squeeze test and rejection test
# -----------------------------------------------------------------------------

#' Perform one (vectorized) round of ARS with a fixed hull.
#'
#' m candidates are drawn from s_k. Each is accepted by the squeeze test
#' w <= exp(l_k(x) - u_k(x)) without evaluating f; otherwise h(x) is evaluated,
#' checked for log-concavity, and the candidate is accepted if
#' w <= exp(h(x) - u_k(x)). Every candidate uses the same hull, so accepted
#' values are exact draws from f; the evaluated points are returned so the
#' caller can refine the hull (the updating step of the paper).
#'
#' @return list(samples, eval_x, eval_h) with eval_* restricted to finite h
ars_step <- function(m, hull, h, tol = 1e-6) {
  x <- sample_envelope(m, hull)
  w <- runif(m)
  u <- eval_upper_hull(x, hull)
  l <- eval_lower_hull(x, hull)
  accept <- w <= exp(l - u)                      # squeezing test
  need <- which(!accept)
  eval_x <- eval_h <- numeric(0)
  if (length(need) > 0L) {
    xe <- x[need]
    he <- h(xe)
    check_points_against_hulls(xe, he, u[need], l[need], tol)
    accept[need] <- w[need] <= exp(he - u[need])  # rejection test
    ok <- is.finite(he)
    eval_x <- xe[ok]; eval_h <- he[ok]
  }
  list(samples = x[accept], eval_x = eval_x, eval_h = eval_h)
}


# -----------------------------------------------------------------------------
#  Main function
# -----------------------------------------------------------------------------

#' Adaptive rejection sampling from a log-concave density.
#'
#' @param f           vectorized function returning the (possibly unnormalized)
#'                    density at a vector of points, e.g. dnorm. Called as
#'                    f(x, ...).
#' @param n           number of samples (positive integer).
#' @param lower,upper domain of the density (may be infinite).
#' @param x_init      optional vector (length >= 2) of starting abscissae inside
#'                    the domain. If lower = -Inf the smallest must lie left of
#'                    the mode; if upper = Inf the largest right of the mode.
#'                    Chosen automatically when NULL.
#' @param ...         further arguments passed to f (and h_prime), e.g. mean, sd.
#' @param domain      alternative to lower/upper: c(lower, upper).
#' @param h_prime     optional derivative of log f, called as h_prime(x, ...).
#'                    A numerical derivative is used when NULL.
#' @param log_density set TRUE if f returns log-density values.
#' @param max_points  maximum number of abscissae kept in the hull.
#' @param tol         relative tolerance used in the log-concavity checks.
#' @return numeric vector of n samples.
ars <- function(f, n, lower = -Inf, upper = Inf, x_init = NULL, ...,
                domain = NULL, h_prime = NULL, log_density = FALSE,
                max_points = 200L, tol = 1e-6) {
  dom <- resolve_domain(lower, upper, domain)
  lower <- dom$lower; upper <- dom$upper
  validate_inputs(f, n, lower, upper, x_init, h_prime, log_density, max_points, tol)
  n <- as.integer(round(n))
  args <- list(...)

  h  <- make_log_density(f, log_density, args)
  hp <- make_log_density_deriv(h, h_prime, lower, upper, args)

  # Initialisation step
  if (is.null(x_init)) x_init <- find_init_points(h, hp, lower, upper)
  x_init <- sort(as.numeric(x_init))
  hx <- h(x_init)
  if (any(!is.finite(hx))) {
    input_error("the density must be positive at the initial abscissae; f is zero at x = ",
                fmt_num(x_init[!is.finite(hx)][1L]), ".")
  }
  hull <- build_hull(x_init, hx, hp(x_init, hx), lower, upper, tol)

  # Sampling / updating steps
  samples <- numeric(n)
  n_acc <- 0L
  batch <- 16L
  max_rounds <- 1000L
  for (round in seq_len(max_rounds)) {
    m <- as.integer(min(ceiling(1.25 * (n - n_acc)) + 10, batch))
    step <- ars_step(m, hull, h, tol)

    n_new <- min(length(step$samples), n - n_acc)
    if (n_new > 0L) {
      samples[n_acc + seq_len(n_new)] <- step$samples[seq_len(n_new)]
      n_acc <- n_acc + n_new
    }
    if (n_acc >= n) return(samples)

    room <- max_points - length(hull$x)
    if (room > 0L && length(step$eval_x) > 0L) {
      take <- seq_len(min(room, length(step$eval_x)))
      ex <- step$eval_x[take]; eh <- step$eval_h[take]
      hull <- update_hull(hull, ex, eh, hp(ex, eh), tol)
    }
    batch <- min(2L * batch, 100000L)
  }
  sampling_error("the sampler failed to generate ", n, " samples after ", max_rounds,
                 " rounds (acceptance rate too low). Try supplying 'x_init' near the mode.")
}


# =============================================================================
#  Formal tests
# =============================================================================

#' Does evaluating `expr` raise a condition of class `class`?
#' @return list(passed, details)
expect_error_class <- function(expr, class) {
  tryCatch({
    force(expr)
    list(passed = FALSE, details = paste0("no error raised (expected ", class, ")"))
  }, error = function(e) {
    if (inherits(e, class)) {
      list(passed = TRUE, details = paste0("caught ", class, ": ", conditionMessage(e)))
    } else {
      list(passed = FALSE, details = paste0("wrong error type (", class(e)[1L], "): ", conditionMessage(e)))
    }
  })
}

#' Compare a sample against a known distribution.
#'
#' Three criteria, all must hold:
#'  * |mean - mu| <= z * sigma / sqrt(n)
#'  * |var - sigma^2| <= z * SE(var), SE(var) = sqrt((m4 - s^4) / n)
#'  * Kolmogorov-Smirnov test against the true CDF has p-value > alpha
#' plus range and length checks. With z = 4 and alpha = 0.001 a correct
#' sampler fails with very small probability, while wrong shapes (e.g. a
#' uniform sample with the right mean/sd) are caught by the KS test.
check_distribution <- function(x, n, mu, sigma, cdf, lower = -Inf, upper = Inf,
                               z = 4, alpha = 0.001) {
  m <- mean(x); s <- sd(x)
  se_mean <- sigma / sqrt(length(x))
  se_var <- sqrt(max(mean((x - m)^4) - s^4, 0) / length(x))
  ks_p <- suppressWarnings(stats::ks.test(x, cdf)$p.value)
  checks <- c(
    length = length(x) == n && is.numeric(x) && all(is.finite(x)),
    range  = all(x >= lower & x <= upper),
    mean   = abs(m - mu) <= z * se_mean,
    sd     = abs(s^2 - sigma^2) <= z * se_var,
    ks     = ks_p > alpha
  )
  details <- sprintf("mean = %.4f (expected %.4f), sd = %.4f (expected %.4f), KS p-value = %.4f",
                     m, mu, s, sigma, ks_p)
  if (!all(checks)) details <- paste0(details, "; failed: ", paste(names(checks)[!checks], collapse = ", "))
  list(passed = all(checks), details = details, mean = m, sd = s)
}

#' Run the formal test-suite.
#'
#' Prints one line per test in the form "TEST_NAME: PASS" / "TEST_NAME: FAIL"
#' followed by details (mean and standard deviation for distributional tests),
#' writes example samples to normal_samples.txt and exponential_samples.txt,
#' and returns a data frame of results invisibly.
#'
#' @param n          sample size for distribution tests
#' @param seed       RNG seed (tests are reproducible)
#' @param output_dir directory for the sample files
test <- function(n = 10000, seed = 1992,
                 output_dir = if (dir.exists("/app")) "/app" else getwd()) {
  set.seed(seed)
  results <- data.frame(test = character(0), passed = logical(0), details = character(0),
                        stringsAsFactors = FALSE)
  saved <- list()

  run <- function(name, description, fun) {
    cat(sprintf("\n[%s] %s\n", name, description))
    res <- tryCatch(fun(), error = function(e) {
      list(passed = FALSE, details = paste0("unexpected error: ", conditionMessage(e)))
    })
    passed <- isTRUE(res$passed)
    cat(sprintf("%s: %s\n", name, if (passed) "PASS" else "FAIL"))
    if (!is.null(res$details) && nzchar(res$details)) cat(sprintf("    %s\n", res$details))
    results[nrow(results) + 1L, ] <<- list(name, passed, as.character(res$details))
    invisible(res)
  }
  section <- function(title) cat(sprintf("\n==== %s ====\n", title))

  cat("Adaptive rejection sampler (Gilks & Wild, 1992) - formal tests\n")
  cat(sprintf("seed = %d, n = %d samples per distributional test\n", seed, n))
  cat("Distributional criteria: |mean - mu| <= 4 SE, |var - sigma^2| <= 4 SE, KS p-value > 0.001\n")

  # ---------------------------------------------------------------------------
  section("1. Input validation")
  run("INPUT_NEGATIVE_N", "n = -5 must be rejected",
      function() expect_error_class(ars(dnorm, -5), "ars_input_error"))
  run("INPUT_ZERO_N", "n = 0 must be rejected",
      function() expect_error_class(ars(dnorm, 0), "ars_input_error"))
  run("INPUT_NON_INTEGER_N", "n = 2.5 must be rejected",
      function() expect_error_class(ars(dnorm, 2.5), "ars_input_error"))
  run("INPUT_NON_NUMERIC_N", "n = \"100\" must be rejected",
      function() expect_error_class(ars(dnorm, "100"), "ars_input_error"))
  run("INPUT_NA_N", "n = NA must be rejected",
      function() expect_error_class(ars(dnorm, NA), "ars_input_error"))
  run("INPUT_INFINITE_N", "n = Inf must be rejected",
      function() expect_error_class(ars(dnorm, Inf), "ars_input_error"))
  run("INPUT_F_NOT_FUNCTION", "f = \"dnorm\" (a string) must be rejected",
      function() expect_error_class(ars("dnorm", 10), "ars_input_error"))
  run("INPUT_DOMAIN_REVERSED", "lower = 5 > upper = 1 must be rejected",
      function() expect_error_class(ars(dnorm, 10, lower = 5, upper = 1), "ars_input_error"))
  run("INPUT_DOMAIN_EMPTY", "lower == upper must be rejected",
      function() expect_error_class(ars(dnorm, 10, lower = 1, upper = 1), "ars_input_error"))
  run("INPUT_DOMAIN_NA", "lower = NA must be rejected",
      function() expect_error_class(ars(dnorm, 10, lower = NA), "ars_input_error"))
  run("INPUT_DOMAIN_VECTOR", "domain = c(1, 2, 3) must be rejected",
      function() expect_error_class(ars(dnorm, 10, domain = c(1, 2, 3)), "ars_input_error"))
  run("INPUT_X_INIT_OUTSIDE", "x_init outside the domain must be rejected",
      function() expect_error_class(ars(dexp, 10, lower = 0, x_init = c(-1, 1)), "ars_input_error"))
  run("INPUT_X_INIT_TOO_SHORT", "x_init of length 1 must be rejected",
      function() expect_error_class(ars(dnorm, 10, x_init = 0), "ars_input_error"))
  run("INPUT_X_INIT_WRONG_SLOPES", "x_init all right of the mode on (-Inf, Inf) must be rejected",
      function() expect_error_class(ars(dnorm, 10, x_init = c(1, 2)), "ars_input_error"))
  run("INPUT_NEGATIVE_DENSITY", "f returning negative values must be rejected",
      function() expect_error_class(ars(function(x) -dnorm(x), 10), "ars_input_error"))
  run("INPUT_NA_DENSITY", "f returning NA must be rejected",
      function() expect_error_class(ars(function(x) rep(NA_real_, length(x)), 10), "ars_input_error"))
  run("INPUT_NOT_VECTORIZED", "non-vectorized f (returns a single value) must be rejected",
      function() expect_error_class(ars(function(x) 1, 10, lower = 0, upper = 1), "ars_input_error"))
  run("INPUT_ZERO_DENSITY_AT_X_INIT", "x_init where the density is zero must be rejected",
      function() expect_error_class(ars(dexp, 10, x_init = c(-2, -1)), "ars_input_error"))
  run("INPUT_SUPPORT_SMALLER_THAN_DOMAIN", "dexp on (-Inf, Inf) without lower = 0 must be rejected",
      function() expect_error_class(ars(dexp, 10), "ars_input_error"))
  run("INPUT_BAD_OPTIONS", "invalid log_density / max_points / tol must be rejected",
      function() {
        r <- list(expect_error_class(ars(dnorm, 10, log_density = "yes"), "ars_input_error"),
                  expect_error_class(ars(dnorm, 10, max_points = 1), "ars_input_error"),
                  expect_error_class(ars(dnorm, 10, tol = -1), "ars_input_error"),
                  expect_error_class(ars(dnorm, 10, h_prime = 3), "ars_input_error"))
        ok <- vapply(r, function(z) z$passed, logical(1))
        list(passed = all(ok), details = sprintf("%d of %d invalid options rejected", sum(ok), length(ok)))
      })

  # ---------------------------------------------------------------------------
  section("2. Module (unit) tests")
  h_norm <- make_log_density(dnorm)
  hp_norm <- make_log_density_deriv(h_norm)

  run("MODULE_LOG_DENSITY", "make_log_density returns log f and honours log_density/extra args",
      function() {
        xs <- c(-2, 0, 1.5)
        e1 <- max(abs(h_norm(xs) - dnorm(xs, log = TRUE)))
        h2 <- make_log_density(dnorm, log_density = TRUE, args = list(mean = 1, sd = 2, log = TRUE))
        e2 <- max(abs(h2(xs) - dnorm(xs, 1, 2, log = TRUE)))
        list(passed = e1 < 1e-12 && e2 < 1e-12,
             details = sprintf("max abs error: %.2e (density input), %.2e (log input)", e1, e2))
      })

  run("MODULE_NUMERIC_DERIVATIVE", "numeric h' matches analytic derivatives (interior and at a boundary)",
      function() {
        xs <- seq(-3, 3, by = 0.5)
        e1 <- max(abs(numeric_derivative(h_norm, xs) - (-xs)))
        h_g <- make_log_density(dgamma, args = list(shape = 3, rate = 2))
        xg <- c(0.1, 1, 4)
        e2 <- max(abs(numeric_derivative(h_g, xg, 0, Inf) - (2 / xg - 2)))
        h_e <- make_log_density(dexp, args = list(rate = 2))
        e3 <- abs(numeric_derivative(h_e, 1e-9, lower = 0) - (-2))     # one-sided at the boundary
        list(passed = e1 < 1e-6 && e2 < 1e-5 && e3 < 1e-6,
             details = sprintf("max abs error: normal %.2e, gamma %.2e, exp at boundary %.2e", e1, e2, e3))
      })

  run("MODULE_INTERSECTIONS", "tangent intersections z_j match closed-form values",
      function() {
        # for h = -x^2/2 tangents at a and b intersect at (a + b) / 2
        x <- c(-1, 0.5, 2)
        z <- compute_intersections(x, -x^2 / 2, -x)
        e1 <- max(abs(z - c(-0.25, 1.25)))
        # for h = 1 - 2x (exponential) tangents coincide -> midpoint is used
        x2 <- c(0, 1, 3)
        z2 <- compute_intersections(x2, 1 - 2 * x2, rep(-2, 3))
        e2 <- max(abs(z2 - c(0.5, 2)))
        # h = log dgamma(shape = 3): tangent intersection by brute force
        x3 <- c(0.5, 2)
        h3 <- 2 * log(x3) - x3; d3 <- 2 / x3 - 1
        z3 <- compute_intersections(x3, h3, d3)
        e3 <- abs((h3[1] + (z3 - x3[1]) * d3[1]) - (h3[2] + (z3 - x3[2]) * d3[2]))
        list(passed = e1 < 1e-12 && e2 < 1e-12 && e3 < 1e-10,
             details = sprintf("errors: quadratic %.1e, parallel %.1e, gamma tangent mismatch %.1e", e1, e2, e3))
      })

  run("MODULE_SEGMENT_MASS", "closed-form segment integrals of exp(u) match numerical integration",
      function() {
        cases <- list(c(x = 0, h = 0.2, b = 1.5, zl = -Inf, zr = 0.3),
                      c(x = 1, h = -1, b = -0.7, zl = 1, zr = Inf),
                      c(x = 1, h = 0.5, b = 0, zl = 0, zr = 2),
                      c(x = 0, h = 0, b = 2, zl = -1, zr = 1),
                      c(x = 3, h = -2, b = -3, zl = 2, zr = 4))
        rel <- vapply(cases, function(cs) {
          exact <- exp(segment_log_mass(cs["x"], cs["h"], cs["b"], cs["zl"], cs["zr"]))
          num <- integrate(function(t) exp(cs["h"] + cs["b"] * (t - cs["x"])), cs["zl"], cs["zr"],
                           rel.tol = 1e-10)$value
          abs(exact - num) / num
        }, numeric(1))
        list(passed = all(rel < 1e-6), details = sprintf("max relative error %.2e over %d segments",
                                                         max(rel), length(rel)))
      })

  run("MODULE_CONCAVITY_CHECK", "check_log_concavity accepts concave h and rejects convex h",
      function() {
        x <- c(-2, -0.5, 1, 2.5)
        ok <- tryCatch(check_log_concavity(x, -x^2 / 2, -x), error = function(e) FALSE)
        bad <- expect_error_class(check_log_concavity(x, x^2, 2 * x), "ars_concavity_error")
        bad2 <- expect_error_class(check_points_against_hulls(3, 1, u = 0, l = -Inf), "ars_concavity_error")
        list(passed = isTRUE(ok) && bad$passed && bad2$passed,
             details = sprintf("concave accepted: %s; convex rejected: %s; point above hull rejected: %s",
                               isTRUE(ok), bad$passed, bad2$passed))
      })

  run("MODULE_HULL_BOUNDS", "lower hull <= log f <= upper hull, with equality at the abscissae",
      function() {
        x <- c(-1.5, -0.2, 0.7, 2)
        hull <- build_hull(x, h_norm(x), -x, -Inf, Inf)
        g <- seq(-8, 8, length.out = 2001)
        hg <- h_norm(g)
        u <- eval_upper_hull(g, hull); l <- eval_lower_hull(g, hull)
        above <- all(u >= hg - 1e-10); below <- all(l <= hg + 1e-10)
        touch <- max(abs(eval_upper_hull(x, hull) - h_norm(x)), abs(eval_lower_hull(x, hull) - h_norm(x)))
        outside <- all(eval_lower_hull(c(-3, 3), hull) == -Inf)
        list(passed = above && below && touch < 1e-10 && outside,
             details = sprintf("u >= h: %s, l <= h: %s, max gap at abscissae %.1e, l = -Inf outside: %s",
                               above, below, touch, outside))
      })

  run("MODULE_UPDATE_HULL", "update_hull inserts points in order and tightens the envelope",
      function() {
        x <- c(-1, 1)
        hull <- build_hull(x, h_norm(x), -x, -Inf, Inf)
        nx <- c(2.5, -0.3)
        hull2 <- update_hull(hull, nx, h_norm(nx), -nx)
        sorted <- !is.unsorted(hull2$x) && length(hull2$x) == 4L
        m1 <- hull_log_total_mass(hull); m2 <- hull_log_total_mass(hull2)
        list(passed = sorted && m2 < m1 && m2 > log(sqrt(2 * pi)),
             details = sprintf("k: 2 -> %d, envelope mass %.4f -> %.4f (true normalizer %.4f)",
                               length(hull2$x), exp(m1), exp(m2), sqrt(2 * pi)))
      })

  run("MODULE_ENVELOPE_SAMPLING", "sample_envelope draws from s_k = exp(u_k)/c (KS test vs numerical CDF)",
      function() {
        x <- c(-2, 0.5, 1.5)
        hull <- build_hull(x, h_norm(x), -x, -Inf, Inf)
        total <- exp(hull_log_total_mass(hull))
        env_cdf <- function(q) vapply(q, function(qq) {
          integrate(function(t) exp(eval_upper_hull(t, hull)), -Inf, qq, rel.tol = 1e-9)$value / total
        }, numeric(1))
        s1 <- sample_envelope(2000, hull)
        p1 <- suppressWarnings(ks.test(s1, env_cdf)$p.value)
        # exact hull for the exponential: envelope is Exp(2) itself
        xe <- c(0.5, 1)
        he <- build_hull(xe, dexp(xe, 2, log = TRUE), c(-2, -2), 0, Inf)
        p2 <- suppressWarnings(ks.test(sample_envelope(2000, he), "pexp", 2)$p.value)
        # flat hull on a bounded interval: envelope is uniform
        hu <- build_hull(c(0.3, 0.6), c(0, 0), c(0, 0), 0, 1)
        p3 <- suppressWarnings(ks.test(sample_envelope(2000, hu), "punif")$p.value)
        list(passed = min(p1, p2, p3) > 0.001,
             details = sprintf("KS p-values: piecewise envelope %.3f, exponential %.3f, uniform %.3f",
                               p1, p2, p3))
      })

  run("MODULE_ARS_STEP", "ars_step accepts every candidate when the hull is exact (exponential)",
      function() {
        xe <- c(0.5, 1)
        hull <- build_hull(xe, dexp(xe, 2, log = TRUE), c(-2, -2), 0, Inf)
        st <- ars_step(1000, hull, make_log_density(dexp, args = list(rate = 2)))
        list(passed = length(st$samples) == 1000L && all(st$samples >= 0),
             details = sprintf("accepted %d of 1000 candidates", length(st$samples)))
      })

  run("MODULE_INIT_POINTS", "find_init_points brackets the mode as required by the envelope",
      function() {
        h1 <- make_log_density(dnorm, args = list(mean = 50, sd = 2))
        p1 <- find_init_points(h1, make_log_density_deriv(h1), -Inf, Inf)
        d1 <- numeric_derivative(h1, p1)
        h2 <- make_log_density(dgamma, args = list(shape = 5, rate = 1))
        p2 <- find_init_points(h2, make_log_density_deriv(h2, lower = 0), 0, Inf)
        d2 <- numeric_derivative(h2, p2, 0, Inf)
        h3 <- make_log_density(dbeta, args = list(shape1 = 2, shape2 = 5))
        p3 <- find_init_points(h3, make_log_density_deriv(h3, lower = 0, upper = 1), 0, 1)
        ok <- d1[1] > 0 && d1[length(d1)] < 0 && d2[length(d2)] < 0 && all(p2 > 0) &&
          all(p3 > 0 & p3 < 1) && length(p3) >= 2
        list(passed = ok,
             details = sprintf("N(50,2): [%s]; Gamma(5): [%s]; Beta(2,5): [%s]",
                               fmt_num(p1), fmt_num(p2), fmt_num(p3)))
      })

  # ---------------------------------------------------------------------------
  section("3. Sampling from known distributions")
  dist_test <- function(name, description, sampler, mu, sigma, cdf, lower = -Inf, upper = Inf, key = NULL) {
    run(name, description, function() {
      t0 <- proc.time()[["elapsed"]]
      x <- sampler()
      el <- proc.time()[["elapsed"]] - t0
      if (!is.null(key)) saved[[key]] <<- x
      res <- check_distribution(x, n, mu, sigma, cdf, lower, upper)
      res$details <- sprintf("%s, time = %.2fs", res$details, el)
      res
    })
  }

  dist_test("NORMAL_STANDARD", "N(0, 1) via ars(dnorm, n)",
            function() ars(dnorm, n), 0, 1, pnorm, key = "normal")
  dist_test("NORMAL_SHIFTED_SCALED", "N(5, 2^2) via ars(dnorm, n, mean = 5, sd = 2)",
            function() ars(dnorm, n, mean = 5, sd = 2), 5, 2,
            function(q) pnorm(q, 5, 2))
  dist_test("EXPONENTIAL", "Exp(rate = 2) on [0, Inf)",
            function() ars(dexp, n, lower = 0, rate = 2), 0.5, 0.5,
            function(q) pexp(q, 2), lower = 0, key = "exponential")
  dist_test("GAMMA", "Gamma(shape = 3, rate = 2) on [0, Inf)",
            function() ars(dgamma, n, lower = 0, shape = 3, rate = 2), 1.5, sqrt(3) / 2,
            function(q) pgamma(q, 3, 2), lower = 0)
  dist_test("BETA", "Beta(2, 3) on [0, 1]",
            function() ars(dbeta, n, lower = 0, upper = 1, shape1 = 2, shape2 = 3), 0.4, 0.2,
            function(q) pbeta(q, 2, 3), lower = 0, upper = 1)
  dist_test("UNIFORM", "Uniform(0, 1) (flat, weakly log-concave) on [0, 1]",
            function() ars(dunif, n, domain = c(0, 1)), 0.5, sqrt(1 / 12), punif, 0, 1)
  a <- 1; lam <- dnorm(a) / (1 - pnorm(a))
  dist_test("TRUNCATED_NORMAL", "N(0, 1) truncated to [1, Inf)",
            function() ars(dnorm, n, lower = 1), lam, sqrt(1 + a * lam - lam^2),
            function(q) (pnorm(q) - pnorm(a)) / (1 - pnorm(a)), lower = 1)
  dist_test("LOGISTIC", "standard logistic distribution",
            function() ars(dlogis, n), 0, pi / sqrt(3), plogis)
  dist_test("WEIBULL", "Weibull(shape = 2, scale = 1) on [0, Inf)",
            function() ars(dweibull, n, lower = 0, shape = 2), gamma(1.5), sqrt(1 - gamma(1.5)^2),
            function(q) pweibull(q, 2), lower = 0)
  dist_test("LAPLACE_KINK", "Laplace(0, 1): log-concave but not differentiable at 0",
            function() ars(function(x) 0.5 * exp(-abs(x)), n), 0, sqrt(2),
            function(q) ifelse(q < 0, 0.5 * exp(q), 1 - 0.5 * exp(-q)))
  dist_test("UNNORMALIZED_DENSITY", "unnormalized 17 * exp(-x^2 / 2) gives N(0, 1)",
            function() ars(function(x) 17 * exp(-x^2 / 2), n), 0, 1, pnorm)
  dist_test("LOG_DENSITY_INPUT", "log-density input: dnorm(log = TRUE), mean = -3, sd = 0.5",
            function() ars(dnorm, n, mean = -3, sd = 0.5, log = TRUE, log_density = TRUE), -3, 0.5,
            function(q) pnorm(q, -3, 0.5))
  dist_test("USER_X_INIT_AND_DERIVATIVE", "N(100, 0.01^2) with user x_init and analytic h_prime",
            function() ars(dnorm, n, x_init = c(99.98, 100.02), mean = 100, sd = 0.01,
                           h_prime = function(x, mean, sd) -(x - mean) / sd^2),
            100, 0.01, function(q) pnorm(q, 100, 0.01))

  run("NEGATIVE_CONTROL_UNIFORM", "the checker must reject uniform values that have the N(0,1) mean and sd",
      function() {
        fake <- runif(n, -sqrt(3), sqrt(3))
        res <- check_distribution(fake, n, 0, 1, pnorm)
        list(passed = !res$passed, details = paste0("checker verdict on fake sample: ",
                                                    if (res$passed) "accepted (bad)" else "rejected (good)",
                                                    "; ", res$details))
      })
  run("OUTPUT_LENGTH_AND_TYPE", "ars returns a numeric vector of exactly n values (n = 1, 7, 2345)",
      function() {
        lens <- vapply(c(1, 7, 2345), function(k) {
          x <- ars(dnorm, k); if (is.numeric(x) && all(is.finite(x))) length(x) else -1
        }, numeric(1))
        list(passed = identical(lens, c(1, 7, 2345)), details = paste("lengths:", paste(lens, collapse = ", ")))
      })
  run("REPRODUCIBILITY", "identical seeds give identical samples",
      function() {
        set.seed(42); a1 <- ars(dgamma, 500, lower = 0, shape = 2)
        set.seed(42); a2 <- ars(dgamma, 500, lower = 0, shape = 2)
        list(passed = identical(a1, a2), details = sprintf("identical: %s", identical(a1, a2)))
      })

  # ---------------------------------------------------------------------------
  section("4. Detection of non-log-concave densities")
  run("NONLOGCONCAVE_CAUCHY", "Cauchy density (heavy tails) must be detected during sampling",
      function() expect_error_class(ars(dcauchy, 2000), "ars_concavity_error"))
  run("NONLOGCONCAVE_STUDENT_T", "Student t (df = 3) must be detected",
      function() expect_error_class(ars(dt, 2000, df = 3), "ars_concavity_error"))
  run("NONLOGCONCAVE_BIMODAL", "bimodal normal mixture must be detected",
      function() expect_error_class(
        ars(function(x) 0.5 * dnorm(x, -3) + 0.5 * dnorm(x, 3), 2000), "ars_concavity_error"))
  run("NONLOGCONCAVE_CONVEX", "exp(x^2) on [-1, 1] (log-convex) must be detected",
      function() expect_error_class(ars(function(x) exp(x^2), 2000, lower = -1, upper = 1),
                                    "ars_concavity_error"))
  run("NONLOGCONCAVE_BETA_U_SHAPED", "U-shaped Beta(0.5, 0.5) on [0, 1] must be detected",
      function() expect_error_class(ars(dbeta, 2000, lower = 0, upper = 1, shape1 = 0.5, shape2 = 0.5),
                                    "ars_concavity_error"))

  # ---------------------------------------------------------------------------
  section("5. Sample files")
  for (key in c("normal", "exponential")) {
    path <- file.path(output_dir, paste0(key, "_samples.txt"))
    run(paste0("WRITE_", toupper(key), "_SAMPLES"), paste("write test samples to", path), function() {
      x <- saved[[key]]
      if (is.null(x)) return(list(passed = FALSE, details = "no samples available"))
      writeLines(sprintf("%.10f", x), path)
      back <- as.numeric(readLines(path))
      list(passed = length(back) == length(x) && max(abs(back - x)) < 1e-9,
           details = sprintf("%d samples written (mean = %.4f, sd = %.4f)", length(back), mean(back), sd(back)))
    })
  }

  # ---------------------------------------------------------------------------
  n_pass <- sum(results$passed)
  cat(sprintf("\n==== SUMMARY: %d of %d tests passed ====\n", n_pass, nrow(results)))
  if (n_pass < nrow(results)) {
    cat("Failed tests:", paste(results$test[!results$passed], collapse = ", "), "\n")
  }
  invisible(results)
}

# Run the test-suite when executed as a script: Rscript ars.R
if (sys.nframe() == 0L) test()

