env_cdf <- function(q) vapply(q, function(qq) {
  zl <- hull$z[-length(hull$z)]; zr <- pmin(hull$z[-1L], qq)
  pieces <- which(zl < qq)
  sum(vapply(pieces, function(j) {
    integrate(function(t) exp(eval_upper_hull(t, hull)), zl[j], zr[j], rel.tol = 1e-9)$value
  }, numeric(1))) / total
}, numeric(1))

