#' Decide the size of the next batch and how many evaluated points may be
#' added to the hull.
#'
#' The paper updates the hull after every single rejection. Vectorizing is
#' much faster in R, but while the envelope is still poor a large batch
#' would put many clustered points into the hull. So while acceptance is
#' low the sampler stays close to the sequential algorithm (small batches,
#' few new points per round); batches double once the envelope is good.
#' @param plan        previous plan (NULL to initialise)
#' @param accept_rate acceptance rate of the last round
#' @return list(batch, max_add)
plan_next_round <- function(plan, accept_rate = 0) {
  small <- 8L
  if (is.null(plan)) return(list(batch = small, max_add = 3L))
  if (accept_rate >= 0.5) {
    list(batch = min(2L * plan$batch, 100000L), max_add = .Machine$integer.max)
  } else {
    list(batch = small, max_add = 3L)
  }
}


