# Sampling / updating steps
samples <- numeric(n)
n_acc <- 0L
plan <- plan_next_round(NULL)
max_rounds <- 20000L
for (round in seq_len(max_rounds)) {
  m <- as.integer(min(ceiling(1.25 * (n - n_acc)) + 10, plan$batch))
  step <- ars_step(m, hull, h, tol)

  n_new <- min(length(step$samples), n - n_acc)
  if (n_new > 0L) {
    samples[n_acc + seq_len(n_new)] <- step$samples[seq_len(n_new)]
    n_acc <- n_acc + n_new
  }
  if (n_acc >= n) return(samples)

  plan <- plan_next_round(plan, accept_rate = length(step$samples) / m)
  n_add <- min(max_points - length(hull$x), plan$max_add, length(step$eval_x))
  if (n_add > 0L) {
    ex <- step$eval_x[seq_len(n_add)]; eh <- step$eval_h[seq_len(n_add)]
    hull <- update_hull(hull, ex, eh, hp(ex, eh), tol)
  }
